<template>
  <el-container style="height: 100%;width: 100%;">
    <!-- 左侧部门树 -->
    <el-aside style="height: 100%;">
      <el-input placeholder="输入关键字进行过滤" v-model="filterText" class="aside-input">
      </el-input>
      <el-tree
        class="aside-tree"
        :data="deptTreeData"
        :props="defaultProps"
        default-expand-all
        node-key="id"
        :filter-node-method="filterNode"
        ref="tree"
      >
      </el-tree>
    </el-aside>
    <!-- 部门用户信息 -->
    <el-main>
    <!-- 头部菜单 - 开始 -->
    <div ref="headerRef">
      <el-row>
        <!-- 搜索框 - 开始 -->
        <el-col :span="18" @keyup.enter.native="handleSearch">
          <el-form inline class="query-form" label-width="5em">
            <el-form-item label="用户名">
              <el-input v-model="searchParam.userName" maxlength="100" placeholder="请输入用户名或用户名称"/>
            </el-form-item>
          </el-form>
        </el-col>
        <!-- 搜索框 - 结束 -->
        <!-- 按钮 - 开始 -->
        <el-col :span="6">
          <el-form inline style="text-align: right">
            <el-form-item>
              <el-button type="primary" @click="clickSearch">查询</el-button>
            </el-form-item>
            <el-form-item>
              <el-button type="info"    @click="handleReset">重置</el-button>
            </el-form-item>
            <el-form-item>
              <el-button type="success" @click="handleShowDialog('add')">添加用户</el-button>
            </el-form-item>
          </el-form>
        </el-col>
        <!-- 按钮 - 结束 -->
      </el-row>
    </div>
    <!-- 头部菜单 - 结束 -->

    <!-- 表格 - 开始 -->
    <el-table :data="tableData" border style="width: 100%; margin-top: 20px" >
      <el-table-column type="index" label="序号" align="center">
        <template slot-scope="scope">
          {{ (currentPage - 1) * pageSize + scope.$index + 1 }}
        </template>
      </el-table-column>
      <el-table-column prop="userName"        label="用户名" show-overflow-tooltip  align="center"/>
      <el-table-column prop="personName" label="用户名称" show-overflow-tooltip align="center"/>
      <el-table-column prop="deptName"          label="部门名称" show-overflow-tooltip align="center"/>
      <el-table-column label="角色/权限" show-overflow-tooltip align="center">
        <template slot-scope="scope">
          {{ deptRoleNameFormat(scope.row.authority)}}
        </template>
      </el-table-column>
      <el-table-column prop="joinTime"          label="入部时间"   show-overflow-tooltip align="center"/>
      <el-table-column label="操作" align="center">
        <template slot-scope="scope">
          <!-- <el-button type="primary" @click="handleShowDialog('edit', scope.row)">编辑</el-button> -->
          <el-button type="danger"  @click="handleDelete(scope.row)">删除</el-button>
        </template>
      </el-table-column>
    </el-table>
    <!-- 表格 - 结束 -->

    <div ref="footerRef">
      <!-- 分页区域 -->
      <el-pagination
        @size-change="handleSizeChange"
        @current-change="handleCurrentChange"
        :current-page="currentPage"
        :page-sizes="[10, 20, 30, 40]"
        :page-size="pageSize"
        layout="total, sizes, prev, pager, next, jumper"
        :total="total"
        style="margin-top: 20px; text-align: center"
      >
      </el-pagination>
    </div>
    </el-main>
  </el-container>
</template>

<script>
import request from "@/utils/request.js"
export default {
    watch: {
      filterText(val) {
        this.$refs.tree.filter(val);
      }
    },
  data() {
    return {
      //左侧树相关变量
      filterText: "", //部门查询条件
      deptTreeData: [], //部门树
      defaultProps: {
        children: "child",
        label: "deptName",
      },//树prop属性
      deptRole:[
        {id:1,label:"超级管理员"},
        {id:2,label:"审核员"},
        {id:3,label:"填报员"},
        {id:4,label:"普通人员"},
      ],//部门角色
      searchParam:{},//查询参数
      sendParam:{},//查询提交参数
      total:0,
      currentPage:1,
      pageSize:10,
      tableData:[],//表格所用数据
    };

  },
  methods: {
    //部门过滤
    filterNode(value, data) {
        if (!value) return true;
        return data.label.indexOf(value) !== -1;
      },
    //获取席位树
    getDeptTree(){
        request.get("/dept/getDeptTree").then(res=>{
            if(res && res.code == 200){
                this.deptTreeData = res.data
            }
        })
    },
    //获取角色名
    deptRoleNameFormat(id){
      return this.deptRole.filter(item=> item.id == id).length >0?this.deptRole.filter(item=> item.id == id)[0].label:""
    },
    //查询按钮
    clickSearch(){
      this.currentPage = 1
      Object.assign(this.sendParam,this.searchParam)
      this.conditionSearch()
    },
    //条件查询
    conditionSearch(){
      request.post("deptUser/searchUserInfoByConditions",{pageNum:this.currentPage,pageSize:this.pageSize,queryParam:this.sendParam}).then(res=>{
        if(res && res.code ==200){
          this.tableData = res.data.data
          this.total = res.data.total
        }
      })
    },
    //删除操作
    handleDelete(row){
      let arr = new Array()
      arr.push(row.dept_userOfId)
      this.$confirm(
        "此操作将删除部门" +row.deptName +"下用户"+row.userName+ ", 是否继续?",
        "提示",
        {
          confirmButtonText: "确定",
          cancelButtonText: "取消",
          type: "warning",
        }
      )
        .then(() => {
          request
            .post("deptUser/deleteUserInDept", {
              ids:arr,
            })
            .then((res) => {
              if (res && res.code == 200) {
                this.$message.success("用户"+row.userName + "删除成功！");
                this.handleReset();
              }
            });
        })
        .catch(() => {
          this.$message({
            type: "info",
            message: "已取消删除",
          });
        });
    },
    handleSizeChange(val) {
      // 每页条数改变时的回调
      this.pageSize = val;
      this.conditionSearch()
    },
    handleCurrentChange(val) {
      // 当前页码改变时的回调
      this.currentPage = val;
     this.conditionSearch()
    },
    //重置查询
    handleReset(){
      this.searchParam = {}
      this.pageSize = 10
      this.clickSearch()
    }
  },
  created(){
    this.getDeptTree()
    this.conditionSearch()
  },
};
</script>
<style>
.aside-input{
    margin: 5px 0;
    min-height: 40px;
    background-color: #F8F9FA;
}
.aside-tree{
    height: calc(100% - 160px);
    background-color: #F8F9FA;
}
</style>
